update invoicing_balance__account
set last_balance_so_far_timestamp = null;

USE vt_balance;
DROP PROCEDURE IF EXISTS update_in_loop_account;

DELIMITER $$
CREATE PROCEDURE update_in_loop_account()
BEGIN


  DECLARE v_min_id, v_max_id BIGINT;
  DECLARE v_batch_size INT DEFAULT 500;

  DECLARE v_sleep_cnt INT DEFAULT 0;
  DECLARE v_sleep_after INT DEFAULT 1000;
  DECLARE v_sleep_time INT DEFAULT 2;

  SELECT MIN(id), MAX(id) INTO v_min_id, v_max_id FROM vt_balance.invoicing_balance__account;
  SELECT v_min_id, v_max_id, v_batch_size;

  WHILE v_min_id <= v_max_id DO

    UPDATE vt_balance.invoicing_balance__account 
    SET last_balance_so_far_timestamp = NULL, last_update = last_update
    WHERE id >= v_min_id AND id < v_min_id + v_batch_size;

    SET v_min_id = v_min_id + v_batch_size;

    SET v_sleep_cnt = v_sleep_cnt + 1;
    SELECT v_min_id, v_max_id, 100*v_min_id/v_max_id AS completed, v_sleep_cnt, v_sleep_after;

    IF v_sleep_cnt > v_sleep_after THEN
      SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
      SELECT SLEEP(v_sleep_time);
      SET v_sleep_cnt = 0;
    END IF;

  END WHILE;
END;
$$
DELIMITER ;{noformat}

